return (
  <div className="space-y-3">
    <div
      role="group"
      className="flex flex-wrap gap-1"
      aria-label={t("projects.filterTypeLabel")}
    >
      {KIND_KEYS.map(({ kind, key }) => {
        // The variant is the only visual cue; assistive technology needs
        // the same state (w4/333).
        const selected = filter.kind === kind;
        return (
          <Button
            key={kind}
            size="sm"
            variant={selected ? "default" : "outline"}
            aria-pressed={selected}
            onClick={() => onChange({ ...filter, kind })}
          >
            {t(key)} ({counts[kind]})
          </Button>
        );
      })}
    </div>

const {
  databases,
  loading: databasesLoading,
  refetch: refetchDatabases,
} = useDatabases();
const {
  keyValues,
  loading: keyValuesLoading,
  refetch: refetchKeyValues,
} = useKeyValues();
const { pending, run } = useServiceLifecycle({ refetch: refetchServices });
const projectResult = projectRoute.useLoaderData();
const project =
  projectResult.state === "ready" ? projectResult.resource : undefined;

const { groups } = useGroupedResources({
  projects: project ? [project] : [],
  services,
  databases,
  keyValues,
});
const group = groups.find((g) => g.id === projectId);

const { rename, busy: renaming } = useRenameProject();
const [renameOpen, setRenameOpen] = useState(false);
const [renameValue, setRenameValue] = useState("");

function refetchAll() {
  void refetchServices();
  void refetchDatabases();
  void refetchKeyValues();
  void router.invalidate();
}

export function filterProjectResources(
  rows: ResourceRow[],
  filter: Pick<ProjectResourceFilterState, "query" | "kind">,
): ResourceRow[] {
  const query = filter.query.trim().toLocaleLowerCase();
  return rows.filter((row) => {
    if (
      filter.kind !== "all" &&
      FILTER_KIND_BY_RESOURCE[row.kind] !== filter.kind
    )
      return false;
    return (
      !query ||
      row.name.toLocaleLowerCase().includes(query) ||
      row.id.toLocaleLowerCase().includes(query)
    );
  });
}

export interface ProjectResourceCounts {
  all: number;
  services: number;
  databases: number;
  keyvalues: number;
  envgroups: number;
}

/** Counts are scoped to the selected Environment and intentionally pre-search. */
export function countProjectResources(
  rows: ResourceRow[],
): ProjectResourceCounts {
  const counts: ProjectResourceCounts = {
    all: rows.length,
    services: 0,
    databases: 0,
    keyvalues: 0,
    envgroups: 0,
  };
  for (const row of rows) {
    counts[FILTER_KIND_BY_RESOURCE[row.kind]] += 1;
  }
  return counts;
}

describe("ProjectResourceFilters selection state (w4/333)", () => {
  it("names the group and presses exactly the current kind", async () => {
    const onChange = vi.fn();
    function Harness() {
      const [filter, setFilter] = useState<ProjectResourceFilterState>({
        environmentId: "evm-1",
        query: "eden",
        kind: "all",
      });
      return (
        <ProjectResourceFilters
          environmentName="production"
          filter={filter}
          counts={counts}
          onChange={(next) => {
            onChange(next);
            setFilter(next);
          }}
        />
      );
    }
    const user = userEvent.setup();
    render(<Harness />);
    const group = screen.getByRole("group", { name: "Resource type" });
    for (const button of within(group).getAllByRole("button")) {
      expect(button).toHaveAttribute("aria-pressed");
    }
    expect(pressedNames()).toEqual(["All (2)"]);

    await user.click(screen.getByRole("button", { name: "Services (2)" }));
    expect(onChange).toHaveBeenLastCalledWith({
      environmentId: "evm-1",
      query: "eden",
      kind: "services",
    });
    expect(pressedNames()).toEqual(["Services (2)"]);

    screen.getByRole("button", { name: "Databases (0)" }).focus();
    await user.keyboard("[Space]");
    expect(pressedNames()).toEqual(["Databases (0)"]);
    screen.getByRole("button", { name: "Env Groups (0)" }).focus();
    await user.keyboard("[Enter]");
    expect(pressedNames()).toEqual(["Env Groups (0)"]);
  });

  it("follows a filter supplied by the parent (URL kind)", () => {
    const filter = (kind: ProjectResourceFilterState["kind"]) => ({
      environmentId: null,
      query: "",
      kind,
    });
    const props = { environmentName: "Unassigned", counts, onChange: vi.fn() };
    const { rerender } = render(
      <ProjectResourceFilters {...props} filter={filter("databases")} />,
    );
    expect(pressedNames()).toEqual(["Databases (0)"]);
    rerender(
      <ProjectResourceFilters {...props} filter={filter("keyvalues")} />,
    );
    expect(pressedNames()).toEqual(["Key Values (0)"]);
  });
});
